steps.script:
GameState.state["meta"]["battle_round"] = 3
for uid in GameState.state["units"]:
	var u = GameState.state["units"][uid]
	if int(u.get("owner", 0)) == 1:
		for m in u.get("models", []):
			if m.get("position") != null:
				m["position"] = {"x": 22.0 * 40.0, "y": 14.75 * 40.0}
				m["base_mm"] = 32
				m["base_type"] = "circular"
for m in GameState.state["units"]["U_STRIKE_FORCE_A"]["models"]:
	m["base_mm"] = 32
	m["base_type"] = "circular"
return GameState.get_battle_round()

var dc = tree.current_scene.deployment_controller
if dc.placed_tokens.size() != 1:
	return "placed %d, expected 1" % dc.placed_tokens.size()
var p: Vector2 = dc.placed_tokens[0].position
var drift := p.distance_to(Vector2(880.0, 200.0)) / 40.0
if drift > 0.05:
	return "clamped %.2f inches away from the click" % drift
return "landed on the click"

GameState.state["meta"]["active_player"] = 1
var dc = tree.current_scene.deployment_controller
var own := 0
var foe := 0
for uid in GameState.state["units"]:
	var u = GameState.state["units"][uid]
	for m in u.get("models", []):
		if m.get("position") != null and m.get("alive", true):
			if int(u.get("owner", 0)) == 2:
				own += 1
			else:
				foe += 1
var from_active := GameState.get_enemy_model_positions(GameState.get_active_player()).size()
var from_owner := GameState.get_enemy_model_positions(dc._placement_owner()).size()
return [dc._placement_owner() == 2, from_active == own, from_owner == foe]
